<template>
  <!-- 外层view：负责拖拽逻辑 -->
  <view
    class="float-wrap"
    :style="{ top: top + 'px', right: right + 'px' }"
    @touchstart="handleTouchStart"
    @touchmove.stop="handleTouchMove"
    @touchend="handleTouchEnd"
  >
    <!-- 内层button：负责原生分享，赠币样式 -->
    <button 
      class="share-btn" 
      open-type="share"
    >
      赠币
    </button>
  </view>
</template>

<script>
export default {
  data() {
    return {
      top: 400,
      right: 10,
      startX: 0,
      startY: 0,
      isDragging: false,
      screenWidth: uni.getWindowInfo ? uni.getWindowInfo().windowWidth : 375,
      screenHeight: uni.getWindowInfo ? uni.getWindowInfo().windowHeight : 667
    }
  },
  methods: {
    handleTouchStart(e) {
      this.isDragging = true;
      this.startX = e.touches[0].clientX;
      this.startY = e.touches[0].clientY;
    },
    handleTouchMove(e) {
      if (!this.isDragging) return;
      const moveX = e.touches[0].clientX - this.startX;
      const moveY = e.touches[0].clientY - this.startY;
      // 限制拖拽范围，避免超出屏幕
      this.left = Math.max(10, Math.min(this.left + moveX, this.screenWidth - 100));
      this.top = Math.max(10, Math.min(this.top + moveY, this.screenHeight - 100));
      this.startX = e.touches[0].clientX;
      this.startY = e.touches[0].clientY;
    },
    handleTouchEnd() {
      this.isDragging = false;
      // 自动吸附到左右侧
      this.left = this.left + 50 > this.screenWidth/2 ? this.screenWidth - 100 : 10;
    }
  }
}
</script>

<style scoped>
/* 外层拖拽容器 */
.float-wrap {
  position: fixed;
  z-index: 9999;
  width: 70rpx;
  height: 70rpx;
  /* 让button完全填充容器 */
  display: flex;
  align-items: center;
  justify-content: center;
}

/* 内层分享button（赠币样式） */
.share-btn {
  width: 100%;
  height: 100%;
  border: none;
  border-radius: 35rpx;
  /* 正常态 */
  background: linear-gradient(135deg, #45b88e, #31926e);
  color: #fff;
  font-size: 22rpx;
  font-weight: bold;
  text-align: center;
  line-height: 70rpx;
  text-align: center;
  padding: 0;
  margin: 0;
  box-shadow: 0 4rpx 12rpx rgba(49, 146, 110, 0.4);
  /* 清除button默认样式 */
  appearance: none;
  -webkit-appearance: none;
}

/* 按钮点击态 */
.share-btn:active {
  background: linear-gradient(135deg, #3aa97e, #287d5c);
  /* 方案1点击态阴影 */
  box-shadow: 0 2rpx 6rpx rgba(49, 146, 110, 0.2);
}
</style>